{
  "items": [
    {
      "name": "Behrend.roth_lower_bound",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, ↑N * Real.exp (-4 * √(Real.log ↑N)) ≤ ↑(rothNumberNat N)"
    },
    {
      "name": "rothNumberNat",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "definition",
      "type": "ℕ →o ℕ"
    },
    {
      "name": "Behrend.bound_aux",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {n d : ℕ}, d ≠ 0 → 2 ≤ n → ↑d ^ (n - 2) / ↑n ≤ ↑(rothNumberNat ((2 * d - 1) ^ n))"
    },
    {
      "name": "Behrend.roth_lower_bound_explicit",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, 4096 ≤ N → ↑N * Real.exp (-4 * √(Real.log ↑N)) < ↑(rothNumberNat N)"
    },
    {
      "name": "Behrend.lower_bound_le_one'",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, 2 ≤ N → N ≤ 4096 → ↑N * Real.exp (-4 * √(Real.log ↑N)) ≤ 1"
    }
  ]
}
